import{_ as n,o as e,c as h,a2 as i}from"./chunks/framework.BBd5PKnH.js";const u=JSON.parse('{"title":"SSR vs CSR","description":"","frontmatter":{"title":"SSR vs CSR","date":"2026-09-11T00:00:00.000Z"},"headers":[],"relativePath":"notes/ssr-vs-csr.md","filePath":"notes/ssr-vs-csr.md"}'),r={name:"notes/ssr-vs-csr.md"};function c(a,t,o,d,l,g){return e(),h("div",null,[...t[0]||(t[0]=[i('<h2 id="_1-đinh-nghia-co-ban" tabindex="-1">1. Định nghĩa cơ bản <a class="header-anchor" href="#_1-đinh-nghia-co-ban" aria-label="Permalink to &quot;1. Định nghĩa cơ bản&quot;">​</a></h2><ul><li><strong>CSR (Client-Side Rendering):</strong> server trả về HTML gần như rỗng (chỉ có khung, ví dụ <code>&lt;div id=&quot;root&quot;&gt;&lt;/div&gt;</code> + thẻ <code>&lt;script&gt;</code>). Trình duyệt tải JS về, JS tự gọi API lấy dữ liệu rồi dựng nội dung ngay trong trình duyệt.</li><li><strong>SSR (Server-Side Rendering):</strong> server tự chạy code, lấy dữ liệu, render sẵn ra HTML đã có đầy đủ nội dung, rồi mới gửi cho trình duyệt. Trình duyệt chỉ việc hiển thị.</li></ul><h2 id="_2-html-va-javascript-đong-vai-tro-gi" tabindex="-1">2. HTML và JavaScript đóng vai trò gì <a class="header-anchor" href="#_2-html-va-javascript-đong-vai-tro-gi" aria-label="Permalink to &quot;2. HTML và JavaScript đóng vai trò gì&quot;">​</a></h2><ul><li><strong>HTML</strong> = cấu trúc/nội dung tĩnh, giống bộ xương của trang.</li><li><strong>JavaScript</strong> = làm trang &quot;sống&quot; — xử lý sự kiện (click, input), gọi API, sửa lại DOM. Giống cơ bắp + não bộ.</li></ul><p>Trình tự trình duyệt tải một trang:</p><ol><li>Gửi request → server trả về HTML (luôn tới trước).</li><li>Trình duyệt đọc HTML từ trên xuống, dựng dần cây DOM.</li><li>Gặp <code>&lt;link&gt;</code> (CSS) hay <code>&lt;script&gt;</code> (JS) thì tải về (script thường sẽ chặn parse HTML cho tới khi tải + chạy xong).</li><li>DOM + CSS dựng xong → trình duyệt vẽ (paint) lên màn hình.</li><li>JS chạy, có thể tiếp tục sửa DOM (thêm tương tác, load thêm dữ liệu...).</li></ol><p>Khác biệt cốt lõi giữa SSR/CSR nằm ở bước 1: HTML đó đã có nội dung thật hay chỉ là cái vỏ rỗng.</p><h2 id="_3-hydration-la-gi" tabindex="-1">3. Hydration là gì <a class="header-anchor" href="#_3-hydration-la-gi" aria-label="Permalink to &quot;3. Hydration là gì&quot;">​</a></h2><p>Với SSR, sau khi HTML (đã có sẵn nội dung) hiển thị xong, React ở client vẫn cần chạy để so khớp (reconcile) cây ảo của nó với HTML tĩnh đó, rồi gắn event listener + khởi tạo state vào đúng chỗ — quá trình này gọi là <strong>hydration</strong>.</p><p>Trước khi hydrate xong, giao diện <em>nhìn</em> đầy đủ nhưng chưa hoạt động được — đây là lý do đôi khi bấm nút &quot;Thêm vào giỏ hàng&quot; ngay lúc trang vừa load xong lại chưa phản ứng gì trong chốc lát.</p><h2 id="_4-build-time-vs-request-time" tabindex="-1">4. Build time vs Request time <a class="header-anchor" href="#_4-build-time-vs-request-time" aria-label="Permalink to &quot;4. Build time vs Request time&quot;">​</a></h2><ul><li><strong>Build time</strong>: lúc chạy lệnh build (<code>next build</code>). Code được compile (TypeScript/JSX → JavaScript thuần) rồi bundle (gộp module, tree-shaking, code-splitting, minify).</li><li><strong>SSG (Static Site Generation) / <code>&#39;use cache&#39;</code></strong>: hàm lấy dữ liệu + render được <strong>chạy thật</strong> ngay lúc build, HTML được lưu sẵn thành file tĩnh. Mọi người nhận cùng một bản HTML cho tới lần build lại hoặc revalidate tiếp theo.</li><li><strong>SSR thật</strong> (<code>getServerSideProps</code>, route đánh dấu dynamic): không chạy lúc build — đợi tới khi có request thật mới chạy. Luôn có dữ liệu mới nhất, nhưng tốn thời gian xử lý ở mỗi request.</li><li><strong>CSR</strong>: build chỉ tạo ra JS bundle + 1 HTML gần như rỗng. Không có bước render nào chạy trước — toàn bộ logic render chỉ thực thi trong trình duyệt của người dùng.</li></ul><h2 id="_5-cach-nhan-biet-ssr-vs-csr-tren-mot-trang-bat-ky" tabindex="-1">5. Cách nhận biết SSR vs CSR trên một trang bất kỳ <a class="header-anchor" href="#_5-cach-nhan-biet-ssr-vs-csr-tren-mot-trang-bat-ky" aria-label="Permalink to &quot;5. Cách nhận biết SSR vs CSR trên một trang bất kỳ&quot;">​</a></h2><ul><li>❌ Tab <strong>Elements</strong> (Inspect) trong F12 — không đáng tin, vì nó luôn hiện DOM <em>sau khi</em> JS đã chạy xong, dù trang là CSR hay SSR.</li><li>✅ <strong>View Page Source</strong> (Ctrl+U, hoặc chuột phải → View Page Source) — hiện đúng HTML thô server gửi, trước khi JS chạy. Có sẵn nội dung → SSR/SSG. Chỉ có div rỗng → CSR.</li><li>✅ Tab <strong>Network</strong> → request đầu tiên (loại Document) → xem tab Response.</li><li>✅ Tắt hẳn JavaScript của trình duyệt rồi tải lại trang.</li><li>✅ Gọi thẳng bằng <code>curl &lt;url&gt;</code> (không chạy JS).</li></ul><h2 id="_6-cache-mac-đinh-khi-fetch-data-trong-next-js" tabindex="-1">6. Cache mặc định khi fetch data trong Next.js <a class="header-anchor" href="#_6-cache-mac-đinh-khi-fetch-data-trong-next-js" aria-label="Permalink to &quot;6. Cache mặc định khi fetch data trong Next.js&quot;">​</a></h2><p>Có 2 mô hình tùy có bật <code>cacheComponents</code> hay không (flag từ Next.js 16+, gộp lại từ 2 flag thử nghiệm cũ <code>dynamicIO</code> + <code>useCache</code>):</p><table tabindex="0"><thead><tr><th></th><th>Mô hình cũ (mặc định)</th><th><code>cacheComponents: true</code></th></tr></thead><tbody><tr><td>Mặc định</td><td>fetch() tự động <strong>được cache</strong></td><td>fetch()/data <strong>dynamic</strong>, không cache</td></tr><tr><td>Muốn đổi hành vi mặc định</td><td>Tắt cache bằng <code>cache: &#39;no-store&#39;</code> hoặc set <code>revalidate</code></td><td>Bật cache bằng đánh dấu <code>&#39;use cache&#39;</code> (kèm <code>cacheLife</code>)</td></tr></tbody></table><h2 id="_7-build-error-vs-runtime-error" tabindex="-1">7. Build error vs Runtime error <a class="header-anchor" href="#_7-build-error-vs-runtime-error" aria-label="Permalink to &quot;7. Build error vs Runtime error&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Build error</th><th>Runtime error (do logic phụ thuộc dữ liệu)</th></tr></thead><tbody><tr><td>Là gì</td><td>Phát hiện chỉ bằng đọc code tĩnh: lỗi cú pháp, import sai, sai kiểu TypeScript</td><td>Chỉ lộ ra khi code thực sự chạy với dữ liệu cụ thể (vd: <code>product.name</code> khi <code>product</code> là <code>undefined</code>)</td></tr><tr><td>CRA (CSR thuần)</td><td>Có, bắt bình thường như mọi project JS/TS</td><td>Không bắt được lúc build (build không chạy component với data thật) — chỉ lộ khi người dùng thật gặp trong trình duyệt</td></tr><tr><td>Next.js SSG / <code>&#39;use cache&#39;</code></td><td>Có, bắt bình thường</td><td>Có thể bắt <strong>ngay lúc <code>next build</code></strong>, vì Next.js thực sự chạy render logic với dữ liệu thật để tạo HTML tĩnh</td></tr><tr><td>Next.js SSR thật / Client Component</td><td>Có, bắt bình thường</td><td>Vẫn chỉ lộ lúc có request thật (lỗi phía server) hoặc lúc chạy trong trình duyệt (lỗi phía client)</td></tr></tbody></table><h2 id="_8-vi-sao-seo-hay-đuoc-nhac-toi-khi-so-sanh-ssr-csr" tabindex="-1">8. Vì sao SEO hay được nhắc tới khi so sánh SSR/CSR <a class="header-anchor" href="#_8-vi-sao-seo-hay-đuoc-nhac-toi-khi-so-sanh-ssr-csr" aria-label="Permalink to &quot;8. Vì sao SEO hay được nhắc tới khi so sánh SSR/CSR&quot;">​</a></h2><p>Bot của công cụ tìm kiếm (và bot lấy preview link) đọc HTML thô — về bản chất giống hệt thao tác &quot;View Source&quot; ở mục 5. Nhiều bot <strong>không chạy được JavaScript</strong>:</p><ul><li>CSR: HTML thô gần như rỗng → bot không thấy nội dung → khó index, ảnh hưởng SEO.</li><li>SSR/SSG: nội dung có sẵn trong HTML thô → bot nào cũng đọc được ngay, không phụ thuộc JS có chạy được hay không.</li></ul><p>Googlebot hiện đại có chạy được JS (dùng trình duyệt headless), nhưng việc này tốn tài nguyên hơn nên thường index CSR chậm hơn (index theo 2 đợt). SSR cũng thường hiển thị nội dung nhanh hơn (tốt cho Core Web Vitals), gián tiếp lợi thêm cho SEO.</p><h2 id="_9-bang-tong-ket" tabindex="-1">9. Bảng tổng kết <a class="header-anchor" href="#_9-bang-tong-ket" aria-label="Permalink to &quot;9. Bảng tổng kết&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>SSR / SSG</th><th>CSR</th></tr></thead><tbody><tr><td>HTML ban đầu</td><td>Có sẵn nội dung</td><td>Gần như rỗng</td></tr><tr><td>Tốc độ thấy nội dung lần đầu</td><td>Nhanh</td><td>Chậm hơn (chờ JS tải + fetch data)</td></tr><tr><td>SEO</td><td>Tốt, mọi bot đọc được</td><td>Phụ thuộc bot có chạy JS hay không</td></tr><tr><td>Bắt lỗi runtime-logic sớm</td><td>SSG/<code>use cache</code>: có thể bắt lúc build</td><td>Không — chỉ lộ ở trình duyệt người dùng</td></tr><tr><td>Dữ liệu luôn mới nhất</td><td>SSR thật: có (render lại mỗi request); SSG: không (cache tới khi revalidate)</td><td>Có (fetch ngay lúc trang chạy)</td></tr><tr><td>Tải server mỗi request</td><td>SSR thật: cao hơn (phải render mỗi lần)</td><td>Thấp hơn (server chỉ trả file tĩnh + JS bundle)</td></tr></tbody></table><h2 id="tham-khao" tabindex="-1">Tham khảo <a class="header-anchor" href="#tham-khao" aria-label="Permalink to &quot;Tham khảo&quot;">​</a></h2><ul><li><a href="https://nextjs.org/docs/app/api-reference/config/next-config-js/cacheComponents" target="_blank" rel="noreferrer">next.config.js: cacheComponents | Next.js</a></li><li><a href="https://nextjs.org/docs/app/getting-started/caching" target="_blank" rel="noreferrer">Getting Started: Caching | Next.js</a></li></ul>',27)])])}const S=n(r,[["render",c]]);export{u as __pageData,S as default};
